-- 609: d2_landed named exceptions and the NWE listing end (ledger 2026-11-21e).
--
-- infra.corpus_rerun.d2_landed.held_verdicts is a JSON list of {symbol, check, evidence}: a 1d
-- verdict that is judged and failing, and named here, does not fail the corpus rerun's d2_landed pin
-- gate and is reported with its evidence (services/rebuild_preconditions.py excuse_held_verdicts).
-- A missing or stale verdict is never excused. Part of rebuild_preconditions.APR_KEYS, so it joins
-- every run's apr_hash. Also the listing_end row of NWE (merged into Bright Horizon Energy; the
-- migration is the sole writer of listing_end). Idempotent; no table is rewritten, so no VACUUM
-- clause is owed.

BEGIN;

INSERT INTO config_schema (config_key, value_type, default_value, min_value, max_value, description)
VALUES
('infra.corpus_rerun.d2_landed.held_verdicts', 'json', '[{"symbol": "MHH", "check": "split_continuity", "evidence": "Yahoo and the Massive reference agree the 1.25 split ex 2013-12-02. Canonical closes 7.59, 7.62, 7.76, 7.06, 8.28, 7.67, 7.91, 7.85 across it are level-continuous; the +0.159 step equals ln(1.25) within tolerance only because the real move that day was +16 percent. Isolated, inactive name."}, {"symbol": "DRIP", "check": "split_continuity", "evidence": "Yahoo matches the 12-for-1 ex 2020-03-27 (Massive raw 239.58 to 23.80). Canonical closes 199.5, 199.6, 238.0, 242.5, 231.8 are level-continuous; the +0.176 step equals ln of the run product 12 x 0.1 = 1.2 only because the real move was +19 percent. Isolated, inactive name."}, {"symbol": "VIP", "check": "split_continuity", "evidence": "Massive raw 1d steps 123.00 to 39.89 on 2004-11-23 (3:1, unadjusted ratio 3.08) while the reference row is dated 2004-11-19, one session early; Yahoo has no split listed, so the tape-only correction path (a second witness is tape plus a vendor agreeing) is not built. One canonical bar (2004-11-22) sits on the wrong scale. Inactive, 2004."}, {"symbol": "ACGN", "check": "split_continuity", "evidence": "Massive raw 1d steps 0.8306 to 6.55 on 2018-07-30 (1-for-8, ratio 7.89) while the reference row is dated 2018-07-26, one session early; no Yahoo history. One canonical bar (2018-07-27) on the wrong scale. Inactive."}, {"symbol": "CETV", "check": "split_continuity", "evidence": "Massive raw 1d halves 30.68 to 15.15 on 2003-11-05 (2:1, ratio 2.03) while the reference row is dated 2003-11-06, so the last old-scale day is 2003-11-04; no Yahoo history. Two canonical bars (2003-11-05 and 2003-11-06) on the wrong scale. Inactive, 2003."}, {"symbol": "ETS", "check": "split_continuity", "evidence": "Massive raw 1d steps 1.27 to 9.97 on 2005-10-31 (1-for-8, ratio 7.85) while the reference row is dated 2005-10-27, one session early; Yahoo history does not cover the date. One canonical bar (2005-10-28) on the wrong scale. Inactive, 2005."}, {"symbol": "ACIW", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-18: log step -0.108 on volume 2.0M vs 0.7M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "AGL", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-18: log step -0.241 on volume 0.79M vs 0.21M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "RCAT", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-17: log step -0.382 on volume 31.8M vs 10.4M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "SNEX", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-19: log step -0.311 on volume 5.2M vs 0.9M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "TROX", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-18: log step -0.254 on volume 19.2M vs 18.1M, after -0.231 on 2026-11-17 on 18.1M vs 3.3M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "WSM", "check": "unexplained_seam", "evidence": "Alpaca bar 2026-11-19: log step -0.164 on volume 4.5M vs 1.9M shares, a large move with a volume spike and no recognised split ratio (a split would step by ln 2 or more); a real earnings or distress move, not a scale break. The check reads only a recent window and clears as it ages out."}, {"symbol": "ACQR", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.839 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "CEP", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.957 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "DKA", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.984 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "ENGN", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.699 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "GGOV", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.426 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "KWT", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.973 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "PACQ~1726293", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.882 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "PRE", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.646 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "RRF", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.457 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "STNL", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.512 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "WTRE", "check": "session_coverage", "evidence": "Inactive name; session coverage 0.997 over its proven span. Canonical holds every day of its Massive raw 1d series (canonical_recompute and digest_fresh pass); the missing sessions are days the vendor serves no bar, the class of the POWI holds in ledger 2026-11-21b."}, {"symbol": "BKH", "check": "freshness_1d", "evidence": "Black Hills merged with NorthWestern and became Bright Horizon Energy (NYSE: HZN) on 2026-11-16; the BKH spelling has no bars after 2026-11-13 (Alpaca answers no_data from 2026-11-16). A symbol change is not a listing end; the name continues as HZN, whose onboarding is a separate step. Held until that lands."}]', NULL, NULL,
 '[user_preference] JSON list (read with json.loads) of {symbol, check, evidence}: failing 1d verdicts the corpus rerun d2_landed gate holds instead of failing, reported with their evidence (ledger 2026-11-21e). Each entry needs written evidence. Not an ML learning target.')
ON CONFLICT (config_key) DO NOTHING;

