INSERT INTO config_history (timestamp, config_key, version, config_value, changed_by, reason)
SELECT NOW(), config_key, 1, config_value, 'migration_609',
       'Initial value for the d2_landed held verdicts (ledger 2026-11-21e)'
  FROM config_state
 WHERE config_key = 'infra.corpus_rerun.d2_landed.held_verdicts'
   AND NOT EXISTS (SELECT 1 FROM config_history h
                   WHERE h.config_key = 'infra.corpus_rerun.d2_landed.held_verdicts'
                     AND h.changed_by = 'migration_609');

INSERT INTO listing_end (symbol, last_session, reason, evidence)
SELECT 'NWE', DATE '2026-11-13', 'merged',
       '{"source": "company press release and vendor tape", "note": "NorthWestern Energy merged into Black Hills (renamed Bright Horizon Energy, NYSE: HZN) at 0.98 HZN per NWE share, closed 2026-11-16; last Massive and Alpaca 1d bar 2026-11-13, Alpaca no_data from 2026-11-16; the Form 25-NSE accession is not recorded"}'::jsonb
